-- pixelrp: the furni library goes back on the shelves.
--
-- 11,797 furniture rows were in the database and on no catalog page at all.
-- They are not new: 31_FullFurniLibrary imported the official Habbo library,
-- 33 and 39 built a catalog for it, and 83_CatalogRestoreDefault then replaced
-- that catalog with the emulator's default dump - written before the import,
-- and with no idea those items exist. The rows survived; their shelves did not.
--
-- This rebuilds the Furni and Staff tabs from 39_CatalogReorg's taxonomy, which
-- was generated for exactly this library: Lines, Themes, Seasonal by holiday and
-- year, per-game Games pages, Functional, Classics, Misc - 291 pages with
-- curated icons, alphabetical throughout, 13,399 items. What it replaces is the
-- default dump's own furni tree, which sells 5,149 items across pages named
-- 'Rares to Sort', 'new rares wouto' and two different 'Trophies'.
--
-- TWO THINGS THIS FILE LEARNED THE HARD WAY, on beta, 2026-09-12:
--
-- 1. IT TAKES ITS PAGE IDS FROM THE TABLE, NOT FROM A LITERAL. The first
--    version read the ranges out of the migrations - 33 and 39 used 920000, 83
--    used 930000 - and picked 940000 as the next free block. It is not free:
--    92 and 94 allocated the Builders tab's hundreds of designer and customs
--    pages from the table's own sequence, so they exist in no file and sit
--    exactly there. Every page id below is @base + n, and @base is taken from
--    MAX(id) at runtime and remembered, so a re-run rebuilds its own range
--    instead of drifting into somebody else's.
--
-- 2. IT BUILDS BEFORE IT CLEARS. The first version deleted the old tree first,
--    so when the inserts collided the shop was already gone and nothing had
--    replaced it. Now the new tree goes in first and the old one is removed at
--    the end: if anything fails, the tabs are still standing.
--
-- NOT TOUCHED: the Builders tab and everything under it - resolved live, the
-- way 83 resolved it, because those pages exist in no migration; the Front Page
-- and Pet Shop tabs; and every functional page under Furni or Staff -
-- Marketplace, Offers, Spaces, Badge Display, Trophies - found by carrying a
-- page_link or a layout other than default_3x3, and re-parented to its tab so
-- it stays reachable when the legacy shelf above it goes.
--
-- CLOTHING STAYS OUT, as since migration 37: granted in the avatar editor, not
-- sold. That is 1,974 rows.
--
-- EXCHANGE FURNI ARE GATED: a CF_ coin redeems for currency when it is placed
-- and every shelf here is free, so a public one would be a mint. Own staff page.
--
-- RARES, LTD AND NFT STAY BEHIND THE STAFF GATE - min_rank 5 in the taxonomy
-- already. Opening one later is an UPDATE on its min_rank.
--
-- Everything is free, per 90_FreeCatalog: the cost columns are written as 0.

SET @furni := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `page_link` = 'furni' LIMIT 1);
SET @staff := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `page_link` = 'staff' LIMIT 1);

-- The base, decided once and remembered. Re-running must land on the same ids,
-- or the previous run's pages become unreachable strays.
CREATE TABLE IF NOT EXISTS `_cat_lib_base` (`base` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO `_cat_lib_base` (`base`)
    SELECT GREATEST(2000000, (SELECT MAX(`id`) + 1000 FROM `catalog_pages`))
      FROM DUAL
     WHERE NOT EXISTS (SELECT 1 FROM (SELECT `base` FROM `_cat_lib_base` LIMIT 1) x);
SET @base := (SELECT `base` FROM `_cat_lib_base` LIMIT 1);

-- 1. Everything under those two tabs RIGHT NOW - computed before a single new
--    page exists, so the new tree can never end up in the set being removed.
DROP TABLE IF EXISTS `_cat_sub`;
CREATE TABLE `_cat_sub` (`id` INT NOT NULL PRIMARY KEY, `tab` INT NOT NULL) ENGINE=InnoDB;
INSERT INTO `_cat_sub` (`id`,`tab`)
    SELECT `id`, `parent_id` FROM `catalog_pages` WHERE `parent_id` IN (@furni, @staff);
INSERT IGNORE INTO `_cat_sub` (`id`,`tab`)
    SELECT c.`id`, s.`tab` FROM `catalog_pages` c JOIN `_cat_sub` s ON c.`parent_id` = s.`id`;
INSERT IGNORE INTO `_cat_sub` (`id`,`tab`)
    SELECT c.`id`, s.`tab` FROM `catalog_pages` c JOIN `_cat_sub` s ON c.`parent_id` = s.`id`;
INSERT IGNORE INTO `_cat_sub` (`id`,`tab`)
    SELECT c.`id`, s.`tab` FROM `catalog_pages` c JOIN `_cat_sub` s ON c.`parent_id` = s.`id`;
INSERT IGNORE INTO `_cat_sub` (`id`,`tab`)
    SELECT c.`id`, s.`tab` FROM `catalog_pages` c JOIN `_cat_sub` s ON c.`parent_id` = s.`id`;
INSERT IGNORE INTO `_cat_sub` (`id`,`tab`)
    SELECT c.`id`, s.`tab` FROM `catalog_pages` c JOIN `_cat_sub` s ON c.`parent_id` = s.`id`;

-- 2. The functional pages among them. A page that addresses itself by page_link,
--    or draws with a layout of its own, is a feature rather than a shelf - the
--    marketplace, the spaces browser, the trophy and badge pickers.
DROP TABLE IF EXISTS `_cat_func`;
CREATE TABLE `_cat_func` (`id` INT NOT NULL PRIMARY KEY, `tab` INT NOT NULL) ENGINE=InnoDB;
INSERT INTO `_cat_func` (`id`,`tab`)
    SELECT s.`id`, s.`tab` FROM `_cat_sub` s JOIN `catalog_pages` p ON p.`id` = s.`id`
     WHERE p.`page_layout` <> 'default_3x3' OR p.`page_link` <> '';
INSERT IGNORE INTO `_cat_func` (`id`,`tab`)
    SELECT c.`id`, f.`tab` FROM `catalog_pages` c JOIN `_cat_func` f ON c.`parent_id` = f.`id`;
INSERT IGNORE INTO `_cat_func` (`id`,`tab`)
    SELECT c.`id`, f.`tab` FROM `catalog_pages` c JOIN `_cat_func` f ON c.`parent_id` = f.`id`;
INSERT IGNORE INTO `_cat_func` (`id`,`tab`)
    SELECT c.`id`, f.`tab` FROM `catalog_pages` c JOIN `_cat_func` f ON c.`parent_id` = f.`id`;

-- 3. What is actually going: the old tree minus the features inside it.
DROP TABLE IF EXISTS `_cat_doomed`;
CREATE TABLE `_cat_doomed` (`id` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO `_cat_doomed` (`id`)
    SELECT s.`id` FROM `_cat_sub` s
     WHERE s.`id` NOT IN (SELECT `id` FROM (SELECT `id` FROM `_cat_func`) x);

-- A kept page whose parent is doomed moves up to its tab, so nothing that still
-- works ends up behind a deleted shelf.
UPDATE `catalog_pages` p JOIN `_cat_func` f ON f.`id` = p.`id`
   SET p.`parent_id` = f.`tab`
 WHERE p.`parent_id` IN (SELECT `id` FROM (SELECT `id` FROM `_cat_doomed`) x);

-- 4. The taxonomy goes in BEFORE anything comes out.
