-- Three guards: the furni must still exist, it must not be clothing or an
-- exchange coin, and it must not already be sold somewhere that SURVIVES this
-- migration - which is what keeps the Builders tab's stock from appearing
-- twice, while still letting the doomed tree's items be re-shelved here.
INSERT INTO `catalog_items` (`page_id`,`item_id`,`catalog_name`,`cost_credits`,`cost_pixels`,`cost_diamonds`,`amount`,`limited_sells`,`limited_stack`,`offer_active`,`extradata`,`badge`,`offer_id`)
SELECT @base + s.`page_off`, s.`item_id`, s.`catalog_name`, 0, 0, 0, s.`amount`, 0, 0, '1', '', '', -1
  FROM `_cat_stock` s
  JOIN `furniture` f ON f.`id` = CAST(s.`item_id` AS UNSIGNED)
 WHERE f.`item_name` NOT LIKE 'clothing\_%'
   AND f.`interaction_type` NOT IN ('purchasable_clothing','exchange')
   AND NOT EXISTS (
        SELECT 1 FROM `catalog_items` ci
         WHERE ci.`item_id` = s.`item_id`
           AND ci.`page_id` NOT IN (SELECT `id` FROM (SELECT `id` FROM `_cat_doomed`) x));

-- 6. The exchange shelf, staff-gated.
INSERT INTO `catalog_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
    VALUES (@base+800,@staff,'Exchange',28,5,0,90,'','default_3x3','','',b'1',b'1');
INSERT INTO `catalog_items` (`page_id`,`item_id`,`catalog_name`,`cost_credits`,`cost_pixels`,`cost_diamonds`,`amount`,`limited_sells`,`limited_stack`,`offer_active`,`extradata`,`badge`,`offer_id`)
SELECT @base+800, CAST(f.`id` AS CHAR),
       LEFT(COALESCE(NULLIF(f.`public_name`,''), f.`item_name`), 100),
       0, 0, 0, 1, 0, 0, '1', '', '', -1
  FROM `furniture` f
 WHERE f.`interaction_type` = 'exchange'
   AND NOT EXISTS (
        SELECT 1 FROM `catalog_items` ci
         WHERE ci.`item_id` = CAST(f.`id` AS CHAR)
           AND ci.`page_id` NOT IN (SELECT `id` FROM (SELECT `id` FROM `_cat_doomed`) x));

-- 7. Whatever the taxonomy has never heard of - a later furni sync, the handful
--    the dump sold that 39 did not know - goes to an A-Z under Misc rather than
--    staying invisible. A shelf with an honest name beats a missing item.
INSERT INTO `catalog_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
    VALUES (@base+900,@base+7,'More Furni',6,1,0,99,'','default_3x3','','',b'1',b'1');
