INSERT INTO `catalog_items` (`page_id`,`item_id`,`catalog_name`,`cost_credits`,`cost_pixels`,`cost_diamonds`,`amount`,`limited_sells`,`limited_stack`,`offer_active`,`extradata`,`badge`,`offer_id`)
SELECT @base + 900 + IF(UPPER(LEFT(f.`item_name`,1)) BETWEEN 'A' AND 'Z',
                                 ASCII(UPPER(LEFT(f.`item_name`,1))) - 63, 1),
       CAST(f.`id` AS CHAR),
       LEFT(COALESCE(NULLIF(f.`public_name`,''), f.`item_name`), 100),
       0, 0, 0, 1, 0, 0, '1', '', '', -1
  FROM `furniture` f
 WHERE f.`item_name` NOT LIKE 'clothing\_%'
   AND f.`interaction_type` NOT IN ('purchasable_clothing','exchange')
   AND NOT EXISTS (
        SELECT 1 FROM `catalog_items` ci
         WHERE ci.`item_id` = CAST(f.`id` AS CHAR)
           AND ci.`page_id` NOT IN (SELECT `id` FROM (SELECT `id` FROM `_cat_doomed`) x));

-- 8. Only now does the old tree go.
DELETE ci FROM `catalog_items` ci JOIN `_cat_doomed` d ON d.`id` = ci.`page_id`;
DELETE p FROM `catalog_pages` p JOIN `_cat_doomed` d ON d.`id` = p.`id`;

-- 9. A page with nothing on it and nothing under it is worse than no page.
DELETE p FROM `catalog_pages` p
 WHERE p.`id` >= @base
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);

DROP TABLE IF EXISTS `_cat_stock`;
DROP TABLE IF EXISTS `_cat_doomed`;
DROP TABLE IF EXISTS `_cat_func`;
DROP TABLE IF EXISTS `_cat_sub`;
